const crypto = require("crypto");

const accessKeyId = "AKIASAJBIV7CL5662E4E";
const secretAccessKey = "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";
const region = "us-east-1";
const bucket = "ivxholding.com";

// Use path-style: s3.amazonaws.com/BUCKET?list-type=2
const method = "GET";
const host = "s3.amazonaws.com";
const canonicalUri = `/${bucket}`;
const canonicalQueryString = "list-type=2&max-keys=5";

const now = new Date();
const amzDate = now.toISOString().replace(/[:-]|\.\d{3}/g, "");
const dateStamp = amzDate.slice(0, 8);

const payloadHash = crypto.createHash("sha256").update("").digest("hex");

const headers = {
  "host": host,
  "x-amz-content-sha256": payloadHash,
  "x-amz-date": amzDate,
};

const canonicalHeaders = Object.keys(headers).sort().map(k => `${k}:${headers[k]}\n`).join("");
const signedHeaders = Object.keys(headers).sort().join(";");

const canonicalRequest = [method, canonicalUri, canonicalQueryString, canonicalHeaders, signedHeaders, payloadHash].join("\n");
const credentialScope = `${dateStamp}/${region}/s3/aws4_request`;
const stringToSign = ["AWS4-HMAC-SHA256", amzDate, credentialScope, crypto.createHash("sha256").update(canonicalRequest).digest("hex")].join("\n");

function sign(key, msg) { return crypto.createHmac("sha256", key).update(msg).digest(); }
const kDate = sign(Buffer.from("AWS4" + secretAccessKey, "utf8"), dateStamp);
const kRegion = sign(kDate, region);
const kService = sign(kRegion, "s3");
const kSigning = sign(kService, "aws4_request");
const signature = crypto.createHmac("sha256", kSigning).update(stringToSign).digest("hex");

const authHeader = `AWS4-HMAC-SHA256 Credential=${accessKeyId}/${credentialScope}, SignedHeaders=${signedHeaders}, Signature=${signature}`;

fetch(`https://${host}${canonicalUri}?${canonicalQueryString}`, {
  headers: {
    "Authorization": authHeader,
    "x-amz-content-sha256": payloadHash,
    "x-amz-date": amzDate,
  },
}).then(async r => {
  const text = await r.text();
  console.log("Status:", r.status);
  if (r.ok) {
    const keys = text.match(/<Key>([^<]+)<\/Key>/g);
    if (keys) keys.forEach(k => console.log("  file:", k.replace(/<\/?Key>/g, "")));
    else console.log("  (empty bucket)");
  } else {
    // Extract error message
    const errCode = text.match(/<Code>([^<]+)<\/Code>/);
    const errMsg = text.match(/<Message>([^<]+)<\/Message>/);
    console.log("ERROR CODE:", errCode?.[1] || "unknown");
    console.log("ERROR MSG:", errMsg?.[1] || text.substring(0, 300));
  }
}).catch(e => console.log("FETCH ERROR:", e.message));
